// CPU-only reference: source hand matrices and ItemModelGenerator alpha contour.
import com.google.gson.*;import java.nio.file.*;import java.util.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
import net.minecraft.SharedConstants;import net.minecraft.server.Bootstrap;import net.minecraft.client.renderer.ItemInHandRenderer;import net.minecraft.client.renderer.texture.SpriteContents;import net.minecraft.client.resources.model.cuboid.*;import net.minecraft.world.entity.HumanoidArm;import com.mojang.blaze3d.vertex.PoseStack;import org.joml.*;
public class ExportHeldItems {
 static class Sprite extends SpriteContents {BufferedImage image;Sprite(){super(null,null,null);}public int width(){return image.getWidth();}public int height(){return image.getHeight();}public it.unimi.dsi.fastutil.ints.IntList getUniqueFrames(){return it.unimi.dsi.fastutil.ints.IntList.of(0);}public boolean isTransparent(int frame,int x,int y){return (image.getRGB(x,y)>>>24)==0;}}
 static JsonArray matrix(PoseStack p){var row=new JsonArray();for(float v:p.last().pose().get(new float[16]))row.add(v);return row;}
 public static void main(String[] args)throws Exception{
  SharedConstants.tryDetectVersion();Bootstrap.bootStrap();var uf=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");uf.setAccessible(true);var unsafe=(sun.misc.Unsafe)uf.get(null);
  var renderer=unsafe.allocateInstance(ItemInHandRenderer.class);var armMethod=ItemInHandRenderer.class.getDeclaredMethod("applyItemArmTransform",PoseStack.class,HumanoidArm.class,float.class);armMethod.setAccessible(true);var swingMethod=ItemInHandRenderer.class.getDeclaredMethod("swingArm",float.class,PoseStack.class,int.class,HumanoidArm.class);swingMethod.setAccessible(true);var matrices=new JsonArray();
  for(var arm:HumanoidArm.values())for(float equip:new float[]{0,.5f,1})for(float swing:new float[]{0,.1f,.5f,.9f,1}){var p=new PoseStack();armMethod.invoke(renderer,p,arm,equip);swingMethod.invoke(renderer,swing,p,arm==HumanoidArm.RIGHT?1:-1,arm);var row=new JsonObject();row.addProperty("left",arm==HumanoidArm.LEFT);row.addProperty("equip",equip);row.addProperty("swing",swing);row.add("matrix",matrix(p));matrices.add(row);}
  var emptyArm=ItemInHandRenderer.class.getDeclaredMethod("renderPlayerArm",PoseStack.class,net.minecraft.client.renderer.SubmitNodeCollector.class,int.class,float.class,float.class,HumanoidArm.class);emptyArm.setAccessible(true);var emptyMatrices=new JsonArray();
  for(float swing:new float[]{0,.1f,.25f,.5f,.75f,.9f,1}){var p=new PoseStack();try{emptyArm.invoke(renderer,p,null,0,0f,swing,HumanoidArm.RIGHT);throw new AssertionError("Expected null Minecraft after animated prefix");}catch(java.lang.reflect.InvocationTargetException e){if(!(e.getCause() instanceof NullPointerException))throw e;}var row=new JsonObject();row.addProperty("swing",swing);row.add("matrix",matrix(p));emptyMatrices.add(row);}
  var displays=new JsonArray();for(boolean left:new boolean[]{false,true}){var p=new PoseStack();new ItemTransform(new Vector3f(13,47,-23),new Vector3f(1.25f/16,-3f/16,2f/16),new Vector3f(.8f,.7f,1.2f)).apply(left,p.last());var r=new JsonObject();r.addProperty("left",left);r.add("matrix",matrix(p));displays.add(r);}
  var sides=ItemModelGenerator.class.getDeclaredMethod("getSideFaces",SpriteContents.class);sides.setAccessible(true);var sprites=new JsonArray();
  for(String name:List.of("diamond","iron_pickaxe","compass_16")){var image=ImageIO.read(Path.of(args[0],"minecraft/textures/item/"+name+".png").toFile());var sprite=(Sprite)unsafe.allocateInstance(Sprite.class);sprite.image=image;var row=new JsonObject();row.addProperty("texture","minecraft:item/"+name);row.addProperty("width",image.getWidth());row.addProperty("height",image.getHeight());var edges=new JsonArray();for(var side:(Collection<?>)sides.invoke(null,sprite)){var c=side.getClass();var x=c.getDeclaredMethod("x");var y=c.getDeclaredMethod("y");var facing=c.getDeclaredMethod("facing");x.setAccessible(true);y.setAccessible(true);facing.setAccessible(true);var e=new JsonArray();e.add(((Enum<?>)facing.invoke(side)).name());e.add((Integer)x.invoke(side));e.add((Integer)y.invoke(side));edges.add(e);}row.add("edges",edges);sprites.add(row);}
  var root=new JsonObject();root.add("hands",matrices);root.add("empty_hands",emptyMatrices);root.add("displays",displays);root.add("sprites",sprites);Files.writeString(Path.of(args[1]),new Gson().toJson(root));
 }
}
